// app/api/chat/route.ts (Next.js App Router)
import Anthropic from "@anthropic-ai/sdk";
import { AnthropicStream, StreamingTextResponse } from "ai"; // Vercel AI SDK

export const runtime = "edge";

export async function POST(req: Request) {
  const { messages } = await req.json();
  const client = new Anthropic();

  const response = await client.messages.create({
    model: "claude-sonnet-5-5",
    max_tokens: 1024,
    messages,
    stream: true,
  });

  // Vercel AI SDK converts Anthropic SSE to a web ReadableStream
  const stream = AnthropicStream(response);
  return new StreamingTextResponse(stream);
}

import anthropic
client = anthropic.Anthropic()

# Full event-level control (not just text)
with client.messages.stream(
    model="claude-haiku-5-5",
    max_tokens=512,
    tools=[{"name": "search", "description": "Search the web",
            "input_schema": {"type": "object", "properties": {"query": {"type": "string"}},
                            "required": ["query"]}}],
    messages=[{"role": "user", "content": "Search for the latest news on AI."}]
) as stream:
    for event in stream:
        if event.type == "content_block_start":
            print(f"Block started: {event.content_block.type}")
        elif event.type == "content_block_delta":
            if hasattr(event.delta, "text"):
                print(event.delta.text, end="", flush=True)
            elif hasattr(event.delta, "partial_json"):
                print(event.delta.partial_json, end="")
        elif event.type == "message_stop":
            print("\n--- Stream complete ---")
